function validate([favoriteCompanies]) {
  if (!Array.isArray(favoriteCompanies) || favoriteCompanies.length < 1 || favoriteCompanies.length > 100) return 'favoriteCompanies needs 1 to 100 lists.';
  const keys = new Set();
  for (const list of favoriteCompanies) {
    if (!Array.isArray(list) || list.length < 1 || list.length > 500) return 'Each list holds 1 to 500 names.';
    if (list.some(name => typeof name !== 'string' || !/^[a-z]{1,20}$/.test(name))) return 'Each name has 1 to 20 lowercase letters.';
    if (new Set(list).size !== list.length) return 'Names inside one list must be distinct.';
    const key = [...list].sort().join(',');
    if (keys.has(key)) return 'No two lists may hold the same set of names.';
    keys.add(key);
  }
  return null;
}

