  // Sort every list once, then test containment with two pointers.
  const sorted = favoriteCompanies.map(list => [...list].sort());
  const inside = (small, big) => {
    let p = 0;
    for (let q = 0; q < big.length && p < small.length; q++) if (big[q] === small[p]) p++;
    return p === small.length;
  };
  const answer = [];
  for (let i = 0; i < sorted.length; i++) {
    let found = false;
    for (let j = 0; j < sorted.length; j++) if (j !== i && inside(sorted[i], sorted[j])) found = true;
    if (!found) answer.push(i);
  }
  return answer;
}

