function generate(rand, size) {
  const large = size === 'large';
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  // A pool of distinct company names.
  const poolSize = large ? 400 : 5;
  const pool = [], names = new Set();
  while (pool.length < poolSize) {
    let name = '';
    const length = large ? int(1, 20) : 1;
    for (let i = 0; i < length; i++) name += 'abcdefghijklmnopqrstuvwxyz'[large ? int(0, 25) : int(0, 4)];
    if (!names.has(name)) { names.add(name); pool.push(name); }
  }
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) { const j = int(0, i); [list[i], list[j]] = [list[j], list[i]]; }
    return list;
  };
  const n = large ? 100 : int(1, 6);
  const lists = [], keys = new Set();
  let total = 0, attempts = 0;
  while (lists.length < n && attempts++ < 10000) {
    let list;
    if (lists.length > 0 && rand() < 0.5) {
      // Derive from an earlier list: drop some names (a subset) or add a few (a superset).
      const base = lists[int(0, lists.length - 1)];
      if (rand() < 0.6 && base.length > 1) list = shuffle([...base]).slice(0, int(1, base.length - 1));
      else list = [...new Set([...base, ...shuffle([...pool]).slice(0, int(1, large ? 20 : 2))])];
    } else {
      list = shuffle([...pool]).slice(0, int(1, large ? 160 : 4));
    }
    if (list.length > 500 || (large && total + list.length > 12000)) continue;
    const key = [...list].sort().join(',');
    if (keys.has(key)) continue;
    keys.add(key);
    lists.push(shuffle(list));
    total += list.length;
  }
  return [lists];
}
